    failReason: "顧客が無料で当然と思っていた領域に、大人の肩書きで$4.99のプレミアム値付けをしてしまった。YouTubeとTikTokが支配する市場で、短尺動画に課金する文化的必然性を作れないまま、「通勤時間」という前提もコロナで消えた。",
    failReasonEn: "They slapped a $4.99 premium on a category customers already expected to be free, armed only with executive pedigree. In a market owned by YouTube and TikTok, they never manufactured a cultural reason to pay for short-form video — and then COVID erased the 'commute time' premise underneath it.",
    otoraComment: "Quibiは「実績ある大人がスタートアップをやる怖さ」の事例。Katzenberg（DreamWorks）+Whitman（HP）の看板で$1.75Bが即集まった。だが「通勤時の10分動画」という前提がコロナで消え、有料転換率10%以下で即死。90日で結論が出た。「プレミアム短尺動画」は誰も求めていなかった、YouTubeもTikTokも無料でそれをやっていた。肩書きがプロダクト感覚を鈍らせる典型。",
    otoraCommentEn: "Quibi is the case study for how scary it is when accomplished grown-ups try to run a startup. The Katzenberg-and-Whitman pedigree pulled in $1.75B instantly. But the 'commute-time 10-minute video' premise died with COVID, paid conversion was under 10%, and it died fast. The verdict was in within 90 days. Nobody wanted 'premium short-form video' — YouTube and TikTok were already giving it away free. A textbook case of titles dulling product instincts.",
