    otoraComment: "虎屋のmoat 5点は「時間でしか作れない参入障壁」。1521年代に京都で皇室御用達、明治維新で東京に連れて行ってもらい、現在18代目。「500年間、皇室が買い続けている」という事実は資金でも技術でも作れない。パリ出店で海外展開もするが、核は変えない。「変わらないことの価値」を知っている会社は、変わり方も知っている。",
    otoraCommentEn: "Toraya's moat score of 5 is 'the kind of barrier only time can build.' Imperial purveyor from 1520s Kyoto, taken to Tokyo by the Meiji court, now in its 18th generation. The simple fact that 'the Imperial Household has kept buying for 500 years' cannot be bought with capital or built with technology. They've opened in Paris, but the core never changes. A company that understands the value of not changing also understands how to change.",
