    situationEn: "Founded in 1804 (Bunka era) by Ishidaya Nizaemon in Matsuoka, Fukui (present-day Eiheiji Town). The brewery sits at the foot of Eiheiji — the head temple of Soto Zen — and uses spring water from the Kuzuryu River with Fukui-grown sake rice. In 1975, 7th-generation brewer Masato Mizuno released 'Kokuryu Daiginjo Ryu,' pioneering sake's transformation from cheap drink to art object. The flagship 'Ishidaya' (named after the founder's house, junmai daiginjo aged 3 years in a snow cellar, sold only by lottery) is legendary in and beyond Japan as the pinnacle of sake.",
