    survivalKeyEn: "A quadruple geographic lock: Eiheiji water, Fukui rice, 8 generations of family, and snow-cellar terroir. On top of that, the 7th generation bet on 'sake as art' in 1975, locking in a unique position as the broader sake market contracts. Hold tradition firm, and pivot time in exactly one place — that is what built 222 years.",
    otoraComment: "黒龍の222年は「守りと攻めの重ね技」。文化元年、曹洞宗大本山・永平寺の麓で石田屋二左衛門が蔵を開いた時点で、地理と宗教の文脈が決まっていた。7代目・水野正人が1975年に「黒龍 大吟醸 龍」を出した瞬間が、この蔵の物語が他の老舗と分岐した点。当時の日本酒は級別制度（特級・一級・二級）の時代で、「美術品としての酒」は狂気扱い。10年経って市場が追いついた。フラッグシップ「石田屋」は創業者の屋号そのもの——過去を背負って未来を書く、という家の哲学の物質化だ。永平寺の座禅と酒造りは、「同じことを繰り返すことで、違う景色に到達する」という一点で完全に同じ道をたどっている。",
    otoraCommentEn: "Kokuryu's 222 years are a layered move: hold and push. When Ishidaya Nizaemon opened his brewery in 1804 at the foot of Eiheiji — head temple of Soto Zen — the geography and the religious context were already locked in. The divergence moment came in 1975, when the 7th generation Masato Mizuno released 'Kokuryu Daiginjo Ryu.' Sake was still trapped under the grade system (Special / First / Second), and 'sake as art' sounded insane. A decade later the market caught up. The flagship 'Ishidaya' is literally the founder's house name — a material form of the family's philosophy: carry the past on your back as you write the future. Zazen at Eiheiji and sake brewing walk the same path on one point: by repeating the same thing, you reach a different landscape.",
