    situation: "永正2年（1505年）、伊丹（兵庫県）で創業。江戸時代には「下り酒」の最高峰として江戸で絶大な人気を誇り、赤穂浪士が討ち入り前夜に飲んだ酒としても知られる。明治に灘（神戸市東灘区御影）へ移転。銘柄・ロゴ（剣と菱形）・製法を521年ほぼ変えていない。山廃仕込み・木桶仕込みという手間のかかる古典製法を現代まで維持。ラベルに「製造年」を入れず、「いつ飲んでも剣菱」の均一性を貫く。社長（白樫家）が代々蔵を継承し、CMも放送されていたが近年は露出を絞り、伝統手法に回帰。",
