    survivalKey: "「剣菱は剣菱の味である」という同語反復を521年守り続けた結果、均一性そのものがブランドになった。製造年ラベルを拒否し、山廃・木桶という最も手間のかかる製法を維持し、規模拡大を拒否する——全ての経営判断が「変わらない」に向けて最適化されている。この徹底ぶりが、室町末期から現代までの時代変化をすべて通過させた。",
    survivalKeyEn: "By holding the tautology 'Kenbishi tastes like Kenbishi' for 521 years, Kenbishi turned uniformity itself into the brand. No vintage label. Yamahai and wooden-vat methods — the most laborious — kept as-is. Scale refused. Every managerial decision optimizes for 'not changing.' That thoroughness is what carried the brewery through every era shift from the late Muromachi to now.",
    otoraComment: "剣菱の521年は「変えないことの暴力的な執念」。山廃仕込みは乳酸菌を自然に取り込む方法で、数週間余計にかかり、失敗リスクも高い。現代の酒造は9割以上が速醸系に移行したが、剣菱はそこに踏み止まった。木桶仕込みも同じで、ステンレスタンクの方が衛生的で管理しやすいのに、木桶を使い続ける。社長は「木桶が雑菌を持つのではなく、雑菌と共生できる菌叢を育てている」と言う。これはニコマコス倫理学のヘクシス（習慣の徳）そのもの——毎日同じことを繰り返すことで、同じではいられない味が生まれる。赤穂浪士が飲んだ剣菱と今の剣菱は、厳密には違う酒だ。だが同じ剣菱なのだ。この矛盾に立ち続けられる蔵が521年を作る。",
    otoraCommentEn: "Kenbishi's 521 years are violent obstinacy about not changing. Yamahai fermentation invites wild lactic acid bacteria, taking extra weeks with higher failure risk; over 90% of modern breweries switched to faster methods — Kenbishi stayed. Same with wooden vats: stainless steel tanks are more sanitary and easier to manage, but Kenbishi keeps the wood. The president puts it this way: 'The wooden vat doesn't carry bad microbes — it cultivates a microbial ecology that can coexist with them.' This is Nicomachean hexis (habituated virtue) made material: by repeating the same thing every day, a taste that cannot remain the same is produced. The Kenbishi the 47 ronin drank and the Kenbishi of today are, strictly, different drinks. And yet they are the same Kenbishi. Only a brewery that can stand inside that contradiction can build 521 years.",
