      moat: "ネットワーク効果は将来のmoat、2004年5月時点ではMySpaceに対し脆弱。大学限定という差別化は意図的な制約だが模倣は容易",
      revenue: "広告は実装中（Y2M広告ネットワーク経由）、収益化は未確立。月数千ドル規模",
