    otoraCommentEn: "The Imperial Hotel's distinctiveness is that it was built for the purpose of receiving heads of state. In 1890, Shibusawa as chief founding promoter reasoned 'for Japan to meet the West as equals in the modern era, we need a hotel to match' and set it up as a matter of national policy. The 1923 Frank Lloyd Wright–designed wing opened on the day of the Great Kantō Earthquake, survived it, and became legend. 135 years later, it's the synonym of Japanese luxury hospitality even in the inbound-tourism era. A founding motivation of 'for the country' carries a strength that doesn't grow stale even after 135 years.",
