      team: "Ben + Jerry, hippie best friends. Being business novices turned out to be the strength.",
      traction: "Became a global brand. Holds a distinct fan base even inside Unilever.",
      moat: "The mission is unreplicable. 'Saying what you think' is the differentiator.",
