    otoraComment: "Ben & Jerry'sの独自性は「Unileverの子会社なのに社会発信を続けられる」こと。2000年の買収時に「独立取締役会で社会ミッションを守る契約」を勝ち取った。普通の会社は大企業に買われると角が取れるが、彼らは契約で角を守った。BLM・LGBTQ・気候変動と堂々と発言、その結果プレミアム価格が正当化される。5ドルの通信教育で始めた親友ヒッピーが、50年続く社会的企業を作った実例。",
    otoraCommentEn: "Ben & Jerry's distinctiveness is 'being a Unilever subsidiary and still keeping up the social advocacy.' When acquired in 2000, they won a contract for an independent board that protects the social mission. Normal companies lose their edges when bought by a giant; they protected theirs with a contract. Speaking openly on BLM, LGBTQ rights, and climate change — and in turn, that justifies a premium price. A real example of two hippie best friends who started with a $5 correspondence course and built a social enterprise that's lasted 50 years.",
    virtue: "アンドレイア（勇気）",
    virtueEn: "Andreia (courage)",
