    otoraCommentEn: "Apple's awe is '50 years of consecutive hits, redefining a category every ten years.' Apple II → Mac → iPod → iPhone → Apple Silicon. Each was called 'too early,' each turned out right. They went through the hell of Jobs's exile and return. The Cook era converted vision into execution and hit $2.4M per employee in revenue — an otherworldly level of efficiency. iMessage, AirDrop, and Apple Watch connectivity form an ecosystem lock-in you can't leave once you're in. Abstinence — refusing to expand the product line — is the biggest weapon.",
