    insightEn: "90 days from bankruptcy. The NeXT acquisition and Jobs's return were the only cards left.",
    situation: "1997年7月、株価は12年来の安値（約$3.2、分割調整後12セント）。前18ヶ月で$15億、Amelio CEO期通算で$16億の累積赤字。PC市場シェアは5%未満まで縮小。Newton MessagePadは事実上失敗、Performa/Quadra/Power Macintoshと製品ラインは無秩序に膨張、Mac OSはWindows 95に劣後。1997年2月にNeXTを$4.29億で買収しJobsが顧問として復帰、7月9日にAmelioを取締役会クーデターで追い出し9月にinterim CEOへ。8月にMicrosoftから$1.5億の出資と5年間のOffice for Mac供給を取り付けて辛うじて延命。",
    situationEn: "July 1997. Stock at a 12-year low (around $3.20, ~12 cents split-adjusted). $1.5B in losses over 18 months, $1.6B cumulative under CEO Gil Amelio. PC market share fell below 5%. The Newton MessagePad had effectively failed, the product line had bloated chaotically across Performa, Quadra and Power Macintosh, and Mac OS lagged behind Windows 95. Apple acquired NeXT for $429M in February 1997, bringing Jobs back as advisor; on July 9 Jobs led a boardroom coup that ousted Amelio, becoming interim CEO that September. In August, a $150M investment from Microsoft plus a five-year Office for Mac commitment barely kept the company alive.",
    scores: { market: 4, problem: 3, solution: 2, team: 4, traction: 2, moat: 2, revenue: 1, financial: 1, efficiency: 1, exit: 3, timing: 3, insight: 5 },
