      traction: "売上は前年比28%減、四半期赤字$700M超、PCシェア5%未満、開発者の離脱続出。「死にゆくプラットフォーム」とWiredが表紙で書いた時期",
      moat: "Macブランドとクリエイター向けソフト資産は残存。ただし参入障壁としては脆弱で、Microsoftに飲まれる寸前",
