    otoraComment: "2001年のAmazonは『Amazon.bomb』と呼ばれ株価$6まで叩かれた、ドットコム崩壊の生贄候補だった。累積赤字$3B、Lehmanは倒産リスクを公言、Pets.com（Amazon出資先）は既に墓場入り。それでもBezosは1997年の初株主レターで『全ては長期のため』と書面で宣言済みで、四半期利益を演出する誘惑を断ち続けた。2001年Q4で初の四半期黒字$5Mを叩き出した瞬間が、AWS（2006年）への助走になった。プロネーシス（実践知）の本質は『短期の評価に殺されない構造を1997年に書面化していた』ことに尽きる。",
    otoraCommentEn: "In 2001, Amazon was 'Amazon.bomb' — stock crushed to $6, a likely sacrificial victim of the dot-com crash. $3B in cumulative losses, Lehman Brothers publicly warning of bankruptcy risk, Pets.com (an Amazon-backed bet) already in the graveyard. Yet Bezos had declared in his 1997 shareholder letter — in writing — 'It's all about the long term,' and refused the temptation to manufacture quarterly profits. Q4 2001's first profitable quarter ($5M) became the runway to AWS (2006). The essence of phronesis here: he had codified, in writing in 1997, the structure that would prevent short-term scoring from killing him.",
