      problem: "Altair 8800 は LED とトグルスイッチのみ。プログラムを書く手段がない、というハードユーザーの実痛。MITS Roberts も BASIC を欲しがっていた",
      solution: "Altair BASIC は 4KB に収まり、実機なしで PDP-10 上の 8080 シミュレータで開発、初回実行で動いた。当時の他のマイコン用言語処理系より明らかに10倍以上の体験差",
      team: "Gates（コンパイラ・営業）+ Allen（システム・ハード理解）の補完。Lakeside School から PDP-10 で実コードを書いてきた異常な早熟ペア。ただし経営経験ゼロ、Traf-O-Data で失敗済み",
