    otoraComment: "30年後にAI半導体で時価総額世界1位になる会社の出発点は、East San JoseのDenny'sの隅に座っていた3人だった。Jensen Huang 30歳、$40Kの自己資金、製品ゼロ、業界からは「3Dはマニア向けのおもちゃ」と笑われていた。最初のNV1は規格選定を誤り商業的に失敗。普通の創業者なら1995年で諦めている。それでもRiva 128（1997年）→GeForce（1999年）→CUDA（2006年）→ディープラーニング（2012年）→ChatGPT（2022年）と、30年かけて「3Dグラフィックは全コンピューティングの基盤」の仮説を証明していった。32点という存続ライン未到達のスコアからS級まで登った稀有な事例。",
    otoraCommentEn: "The starting point of the company that would become the world's most valuable in AI silicon, 30 years later, was three people in the corner of a Denny's in East San Jose. Jensen Huang at 30, $40K of personal money, zero product, and an industry that laughed at 3D graphics as 'a toy for hobbyists.' Their first product, NV1, picked the wrong standard and flopped. A normal founder would have quit in 1995. Instead, over 30 years, they walked the path: Riva 128 (1997) → GeForce (1999) → CUDA (2006) → deep learning (2012) → ChatGPT (2022) — proving the thesis that 'graphics processing is the foundation of all computing.' A rare case of a company that started below the survival line at 32 points and climbed all the way to S-tier.",
