    survivalKeyEn: "When the entire industry called 3D graphics 'a hobbyist toy,' they held onto a counter-thesis to the 'CPU is enough' consensus, and refused to quit even after NV1's 1995 failure. Starting from $40K and grinding the same thesis for 30 years, that persistence bloomed — at the arrival of the AI era — into 20 years of software-compatibility moat.",
