    failReasonEn: "A structural failure rooted in the lack of courage to destroy its own largest revenue source (film). Even though they invented the world's first digital camera in 1975, they kept delaying commercialization. The most famous case study of the Innovator's Dilemma (Christensen). The contradiction — the more you protect film, the higher the risk that digital adoption erases demand — was never resolved. The success patterns of management blocked the pivot.",
    otoraComment: "Kodakは「Innovator's Dilemma」（クリステンセン）の最も有名な事例。1975年に世界初のデジタルカメラを社内で発明していたのに、フィルム事業（年商$100億）を守るために商業化を遅延した。経営陣の意識は「我々はフィルム会社」のまま。デジタルが来た時、自社で破壊する勇気がなかった。2012年破産。「成功体験が次の失敗を作る」教訓の代名詞。再上場後は素材化学事業で再生中だが、栄光は二度と戻らない。",
    otoraCommentEn: "Kodak is the most famous case of the Innovator's Dilemma (Christensen). Even though they invented the world's first digital camera in-house in 1975, they delayed commercialization to defend their film business ($10B in annual revenue). Management's mental model stayed 'we are a film company.' When digital arrived, they didn't have the courage to destroy themselves. Bankruptcy in 2012. The phrase 'past success creates the next failure' is essentially Kodak. Reborn after re-listing in materials chemistry, but the glory will never come back.",
