    failReasonEn: "A triple blow of 'accounting fraud + Westinghouse nuclear losses + executive dysfunction.' In 2015 a seven-year, $1B accounting fraud came to light, costing three CEOs their seats. Westinghouse — acquired for $5.4B in 2006 — booked over $6B in losses after Fukushima. Selling the semiconductor memory business for $18B bought time, but in 2023 the company was taken private via a JIP TOB. A 150-year blue-chip pushed to the edge of dismantlement. A textbook case of how the Showa-era assumption 'we won't fail if we partner with government' accelerated collapse.",
    otoraComment: "東芝は「150年の名門が解体寸前」の象徴。2015年の$10億会計不正で社長3代が辞任、Westinghouse原発事業で$60億超の損失、半導体メモリ$180億売却、2023年JIPにTOBで上場廃止——日本最古級電機メーカーの撤退。経営層の不正＋取締役会機能不全＋政府との癒着で大企業病が極まった。「Too big to fail」が「Too rotten to save」になった瞬間。三井・住友・三菱が400年生き残る一方で、東芝は150年で解体寸前。何が違うか考えさせる事例。",
    otoraCommentEn: "Toshiba is the symbol of 'a 150-year blue-chip on the brink of dismantlement.' A $1B accounting fraud in 2015 forced three CEO resignations, the Westinghouse nuclear business booked over $6B in losses, the semiconductor memory business was sold for $18B, and in 2023 the company was taken private via a JIP TOB — the retreat of one of Japan's oldest electronics names. Executive fraud + a dysfunctional board + cozy government ties pushed big-company disease to its limit. The moment 'too big to fail' became 'too rotten to save.' While Mitsui, Sumitomo, and Mitsubishi have survived 400 years, Toshiba reached the edge of dismantlement in 150. A case that asks: what was different?",
    virtue: "ヘクシス（習慣的卓越性）",
    virtueEn: "Hexis (habituated excellence)",
