  "NVIDIA|1993|startup": { value: 0, reason: "[加点なし] Denny's 3人会議+$40K自己資金、製品ゼロ、NV1も商業失敗(1995)", reasonEn: "[No bonus] Denny's three-founder meeting + $40K self-funded; no product; even NV1 (1995) was a commercial failure" },
